create or replace function private.toolbox_issues_host_member(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=(select auth.uid()) and wm.active is true) $$;
create or replace function private.toolbox_issues_role(p_workspace_id uuid) returns text language sql stable security definer set search_path='' as $$ select m.role from public.toolbox_issues_memberships m where m.workspace_id=p_workspace_id and m.user_id=(select auth.uid()) and m.enabled limit 1 $$;
create or replace function private.toolbox_issues_has_access(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.toolbox_issues_host_member(p_workspace_id) and exists(select 1 from public.toolbox_issues_memberships m where m.workspace_id=p_workspace_id and m.user_id=(select auth.uid()) and m.enabled) $$;
create or replace function private.toolbox_issues_can_configure_roles(p_workspace_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.toolbox_issues_role(p_workspace_id)='team_leader' $$;
create or replace function private.toolbox_issues_profile_json(p_user uuid) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce((select jsonb_build_object('id',p.id::text,'name',coalesce(p.display_name,p.email,'User'),'email',coalesce(p.email,''),'photo_thumb',null) from public.profiles p where p.id=p_user),jsonb_build_object('id',p_user::text,'name','User','email','','photo_thumb',null)) $$;
create or replace function private.toolbox_issue_asset_json(a public.toolbox_issue_attachments) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',a.id::text,'name',a.name,'size',a.size_bytes,'contentType',a.mime_type,'storagePath',a.storage_path,'url',null,'downloadUrl',null) $$;
create or replace function private.toolbox_issue_update_json(u public.toolbox_issue_updates) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',u.id::text,'text_body',u.text_body,'created_at',u.created_at,'creator',private.toolbox_issues_profile_json(u.creator_user_id),'assets',coalesce((select jsonb_agg(private.toolbox_issue_asset_json(a) order by a.created_at) from public.toolbox_issue_attachments a where a.workspace_id=u.workspace_id and a.update_id=u.id),'[]'::jsonb)) $$;
create or replace function private.toolbox_issue_subitem_json(s public.toolbox_issue_subitems) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(s.payload,'{}'::jsonb)||jsonb_build_object('id',s.id::text,'name',s.name,'status',s.status,'person',s.person,'boardId','18370784141','version',s.version,'createdAt',s.created_at,'updatedAt',s.updated_at) $$;
create or replace function private.toolbox_issue_json(i public.toolbox_issues) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(i.payload,'{}'::jsonb)||jsonb_build_object('id',i.id::text,'name',i.name,'status',i.status,'person',i.person,'date',i.target_date,'timeTracking',i.time_tracking,'creator',private.toolbox_issues_profile_json(i.creator_user_id),'createdAt',i.created_at,'updatedAt',i.updated_at,'version',i.version,'subitems',coalesce((select jsonb_agg(private.toolbox_issue_subitem_json(s) order by s.id) from public.toolbox_issue_subitems s where s.workspace_id=i.workspace_id and s.issue_id=i.id),'[]'::jsonb),'updates',coalesce((select jsonb_agg(private.toolbox_issue_update_json(u) order by u.created_at desc) from public.toolbox_issue_updates u where u.workspace_id=i.workspace_id and u.issue_id=i.id),'[]'::jsonb),'assets',coalesce((select jsonb_agg(private.toolbox_issue_asset_json(a) order by a.created_at) from public.toolbox_issue_attachments a where a.workspace_id=i.workspace_id and a.issue_id=i.id and a.update_id is null),'[]'::jsonb)) $$;;
